CREATE OR REPLACE FUNCTION public.research_benchmark_shortfall_latest(a uuid, s uuid)
 RETURNS research_benchmark_shortfalls
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
